cd /tmp && cat > /tmp/t.mjs <<'EOF'
import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/courier-g2-1/bot.mjs";
const tokyo = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const r = (g,u,iso)=>g.attempt(u,new Date(iso));
let g = createPushGate();
// Tokyo = UTC+9. 12:00 JST = 03:00Z
assert.deepEqual(r(g,tokyo,"2026-10-22T03:00:00Z"),{allowed:true,reason:null});
// 22:00 JST = 13:00Z quiet; 06:59 JST = 21:59Z quiet; 07:00 JST = 22:00Z ok
assert.equal(r(g,tokyo,"2026-10-22T13:00:00Z").reason,"quiet_hours");
assert.equal(r(g,tokyo,"2026-10-22T21:59:00Z").reason,"quiet_hours");
assert.equal(r(g,tokyo,"2026-10-22T21:59:00Z").allowed,false);
assert.equal(r(g,tokyo,"2026-10-22T21:59:00Z").reason,"quiet_hours");
// cap: 3 per local day
g = createPushGate();
for (const h of ["00:00","01:00","02:00"]) assert.equal(r(g,tokyo,`2026-10-22T${h}:00Z`).allowed,true); // 09,10,11 JST
assert.equal(r(g,tokyo,"2026-10-22T03:00:00Z").reason,"daily_cap_reached");
// 14:59Z = 23:59 JST quiet, not cap-confused; next local day 07:00 JST (22:00Z) resets
assert.equal(r(g,tokyo,"2026-10-22T22:00:00Z").allowed,true);
// UTC midnight is not a reset: 15:00Z is 00:00 JST next day (quiet); LA user check
const la = { id:"u2", timeZone:"America/Los_Angeles", quietStart:"22:00", quietEnd:"07:00", dailyCap:2 };
g = createPushGate();
assert.equal(r(g,la,"2026-10-22T18:00:00Z").allowed,true); // 11:00 PDT
assert.equal(r(g,la,"2026-10-22T20:00:00Z").allowed,true);
assert.equal(r(g,la,"2026-10-23T01:00:00Z").reason,"daily_cap_reached"); // 18:00 PDT, UTC day changed but local same
assert.equal(r(g,la,"2026-10-23T14:00:00Z").allowed,true); // next local day 07:00 PDT
// independent users and gates
assert.equal(r(g,{...la,id:"u3"},"2026-10-23T01:00:00Z").allowed,true);
assert.equal(r(createPushGate(),la,"2026-10-23T01:00:00Z").allowed,true);
// refused calls not counted
g = createPushGate(); const c1={...la,dailyCap:1};
assert.equal(r(g,c1,"2026-10-23T08:00:00Z").reason,"quiet_hours");
assert.equal(r(g,c1,"2026-10-23T18:00:00Z").allowed,true);
// daytime window, equal window, cap 0, invalid
const day={...la,quietStart:"13:00",quietEnd:"15:00"};
assert.equal(r(createPushGate(),day,"2026-10-22T21:00:00Z").reason,"quiet_hours"); // 14:00 PDT
assert.equal(r(createPushGate(),{...la,quietStart:"08:00",quietEnd:"08:00"},"2026-10-22T15:00:00Z").allowed,true);
assert.equal(r(createPushGate(),{...la,dailyCap:0},"2026-10-22T18:00:00Z").reason,"daily_cap_reached");
assert.equal(r(createPushGate(),{...la,timeZone:"Nope/Zone"},"2026-10-22T18:00:00Z").reason,"invalid_time_zone");
assert.equal(r(createPushGate(),{...la,quietStart:"25:00"},"2026-10-22T18:00:00Z").reason,"invalid_quiet_hours");
assert.equal(createPushGate().attempt(la,new Date("x")).reason,"invalid_time");
// DST fall-back day (LA 2026-11-01 has 25h): local day still one day
g = createPushGate(); const d2={...la,dailyCap:2};
assert.equal(r(g,d2,"2026-11-01T08:30:00Z").allowed,true); // 00:30 PDT quiet? 
console.log("done");
EOF
